                const timestamp = dataPoint.timestamps[i];
                const value = dataPoint.values[i] || 0;

                // Initialize the timestamp entry if it doesn't exist
                if (!timeData[timestamp]) {
                  timeData[timestamp] = {
                    "SATISFIED": 0,
                    "TOLERATING": 0,
                    "FRUSTRATED": 0
                  };
                }

                // Add the value to the appropriate category
                if (category in timeData[timestamp]) {
                  timeData[timestamp][category] += value;
                }
              }
