import { metricsClient } from "@dynatrace-sdk/client-classic-environment-v2";

export default async function () {
  const startTime = $dt_timeframe_from;
  const endTime = $dt_timeframe_to;
  const AppName = "MyTimesheet";
  // Build Apps List for filter
  var appsList = "\"" + AppName + "\"";
  let i = 1;
  while (i < 10) {
    if (AppName == null) break;
    appsList = appsList + ",\"" + AppName + "\"";
    i++;
  }

  // Simplified metric selector for overall Apdex
  const metricSelector = "builtin:apps.web.apdex.userType:splitBy()";

  try {
    // Fetch overall Apdex value
    const apdexResult = await metricsClient.query({
      metricSelector: metricSelector,
      from: startTime,
      to: endTime,
      resolution: "Inf",
      acceptType: "application/json; charset=utf-8"
    });

    // Fetch timeseries data for the trend graph
    const timeseriesResult = await metricsClient.query({
      metricSelector: metricSelector,
      from: startTime,
      to: endTime,
      resolution: "5m",  // 5-minute intervals for more detailed trend
      acceptType: "application/json; charset=utf-8"
    });

    // Get overall Apdex value
    let overallApdex = 0;
    if (apdexResult.result && apdexResult.result.length > 0) {
      for (const metricData of apdexResult.result) {
        if (metricData.data && metricData.data.length > 0) {
          for (const dataPoint of metricData.data) {
            if (dataPoint.values && dataPoint.values.length > 0) {
              overallApdex = dataPoint.values[0];
              break;
            }
          }
        }
      }
    }

    // Process timeseries data
    const timeseriesData = [];
    if (timeseriesResult.result && timeseriesResult.result.length > 0) {
      for (const metricData of timeseriesResult.result) {
        if (metricData.data && metricData.data.length > 0) {
          for (const dataPoint of metricData.data) {
            if (dataPoint.timestamps && dataPoint.values) {
              // Each datapoint may have multiple timestamps/values
              for (let i = 0; i < dataPoint.timestamps.length; i++) {
                if (dataPoint.values[i] !== null && dataPoint.values[i] !== undefined) {
                  timeseriesData.push({
                    timestamp: dataPoint.timestamps[i],
                    apdex: dataPoint.values[i]
                  });
                }
              }
            }
          }
        }
      }

      // Sort by timestamp
      timeseriesData.sort((a, b) => a.timestamp - b.timestamp);
    }

    // Calculate satisfaction percentages for the donut chart
    // Apdex thresholds: >0.93 Excellent, >0.85 Good, >0.7 Fair, <=0.7 Poor
    // These are typical thresholds but can be adjusted
    const satisfied = timeseriesData.filter(d => d.apdex > 0.93).length;
    const good = timeseriesData.filter(d => d.apdex > 0.85 && d.apdex <= 0.93).length;
    const fair = timeseriesData.filter(d => d.apdex > 0.7 && d.apdex <= 0.85).length;
    const poor = timeseriesData.filter(d => d.apdex <= 0.7).length;

    const total = timeseriesData.length || 1; // Avoid division by zero

    const satisfiedPercentage = (satisfied / total * 100).toFixed(2);
    const goodPercentage = (good / total * 100).toFixed(2);
    const fairPercentage = (fair / total * 100).toFixed(2);
    const poorPercentage = (poor / total * 100).toFixed(2);

    // Determine the Apdex rating text
    let apdexRating;
    if (overallApdex > 0.93) {
      apdexRating = "Excellent";
    } else if (overallApdex > 0.85) {
      apdexRating = "Good";
    } else if (overallApdex > 0.7) {
      apdexRating = "Fair";
    } else if (overallApdex >= 0.5) {
      apdexRating = "Poor";
    } else {
      apdexRating = "Unacceptable";
    }

    // Return data formatted for visualization
    return {
      // Overall Apdex value for gauge
      apdex: overallApdex.toFixed(2),
      apdexRating: apdexRating,

      // Timeseries data for trend
      timeseries: timeseriesData,

      // Distribution data for donut chart
      distribution: {
        satisfied: satisfiedPercentage,
        good: goodPercentage,
        fair: fairPercentage,
        poor: poorPercentage
      },

      // Raw data for debugging
      rawData: {
        satisfied,
        good,
        fair,
        poor,
        total
      }
    };

  } catch (error) {
    console.error("Error fetching metrics:", error);
    return {
      apdex: "0.00",
      apdexRating: "Unknown",
      timeseries: [],
      distribution: {
        satisfied: 0,
        good: 0,
        fair: 0,
        poor: 0
      },
      error: {
        message: error.message
      }
    };
  }
}
